import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
instructions = data[1:]

current_position = 0
valid = True

for instruction in instructions:
    t, direction = instruction.split()
    t = int(t)

    if current_position == 0 and direction != "South":
        valid = False
        break
    elif current_position == 20000 and direction != "North":
        valid = False
        break
    elif direction == "North":
        current_position -= t
    elif direction == "South":
        current_position += t

if current_position != 0:
    valid = False

if valid:
    print("YES")
else:
    print("NO")

